  `amenities_json` json DEFAULT NULL,
  `categories_json` json DEFAULT NULL,
  `cuisines_json` json DEFAULT NULL,
  `diets_json` json DEFAULT NULL,
  `suitable_for_json` json DEFAULT NULL,
  PRIMARY KEY (`tower_item_id`),
  UNIQUE KEY `uq_item_tower` (`item_type`,`item_id`),
  KEY `idx_item_type` (`item_type`),
  KEY `idx_location` (`latitude`,`longitude`),
  KEY `idx_price` (`price`),
  CONSTRAINT `chk_star_rating` CHECK (((`star_rating` is null) or (`star_rating` between 1 and 5)))
