INSERT INTO `tours` VALUES (1,2,1,'Tour Châu Đốc – Núi Sam – Rừng Tràm Trà Sư 1 Ngày','Hành trình khám phá An Giang đưa du khách đến với vùng đất tâm linh và sinh thái đặc trưng miền Tây. Tour kết hợp tham quan Miếu Bà Chúa Xứ Núi Sam linh thiêng, Tây An Cổ Tự cổ kính, Lăng Thoại Ngọc Hầu và trải nghiệm ngồi xuồng len lỏi giữa rừng tràm Trà Sư xanh mát. Phù hợp cho du khách yêu thiên nhiên, văn hóa và không gian yên bình.','An Giang','Thành phố Châu Đốc, Châu Đốc, Phường Châu Đốc, Tỉnh An Giang, Việt Nam',10.68785760,105.09667200,'2024-12-16','2027-09-11',120000.00,'VND',20,10,20,'https://res.cloudinary.com/tripfinity-img/image/upload/v1765861788/assets/a0a2a814-6820-483a-bf49-e7bc5b610501.jpg','[\"https://res.cloudinary.com/tripfinity-img/image/upload/v1765861791/assets/0991bd34-9528-4162-b8b6-d1361833137d.jpg\", \"https://res.cloudinary.com/tripfinity-img/image/upload/v1765861793/assets/8278844b-898f-43ee-a7ce-13f4030b39b0.jpg\"]','[\"hot_deal\",\"recommended\"]','published','public_',1,1000,'moderate','Trung tâm thành phố','Trung tâm thành phố','vietnamese,chinese,korean,french,japanese,english','[\"vietnamese\", \"chinese\", \"korean\", \"french\", \"japanese\", \"english\"]','Tour kéo dài 1 ngày','[{\"day\": 1, \"title\": \"Khám phá\", \"activities\": [\"Khám phá cả ngày\"]}]','hotel,breakfast,meals,lunch,dinner,entrance_fees,activities','flights,visa,personal_expenses','[\"hotel\", \"breakfast\", \"meals\", \"lunch\", \"dinner\", \"entrance_fees\", \"activities\"]','[\"flights\", \"visa\", \"personal_expenses\"]','Hủy trước 7 ngày','– Giá tour bao gồm xe đưa đón, vé tham quan, xuồng rừng tràm và hướng dẫn viên\n– Không bao gồm chi phí cá nhân và ăn uống ngoài chương trình\n– Trẻ em dưới 5 tuổi miễn phí, từ 5–10 tuổi tính 70% giá tour\n– Hủy tour trước 3 ngày được hoàn 50%, hủy sát ngày không hoàn tiền','group','[\"culture\", \"adventure\", \"beach\", \"city\", \"religious\", \"historical\", \"mountain\", \"food\", \"nature\", \"wildlife\", \"photography\"]','[\"pickup\", \"professional_guide\", \"airport_transfer\", \"photographer\", \"wifi_on_board\", \"vegetarian_options\", \"bike_rental\", \"sun_protection\", \"helmet\"]','tour-chau-doc-nui-sam-rung-tram-tra-su-1-ngay-251970648','Tour Châu Đốc Núi Sam Rừng Tràm Trà Sư 1 Ngày Giá Tốt','Khám phá An Giang với tour Châu Đốc – Núi Sam – Rừng Tràm Trà Sư 1 ngày, trải nghiệm tâm linh và thiên nhiên miền Tây đặc sắc, lịch trình trọn gói, giá hấp dẫn.','2025-12-16 05:09:51','2025-12-16 05:09:51','2025-12-16 14:26:43'),(2,2,1,'Tour Châu Đốc – Núi Cấm – Rừng Tràm Trà Sư 2 Ngày 1 Đêm','Hành trình khám phá An Giang với núi non linh thiêng, rừng tràm sinh thái và đời sống văn hóa đặc trưng miền Tây.','An Giang','Thành phố Châu Đốc, Tỉnh An Giang, Việt Nam',10.70096000,105.12005000,'2024-12-16','2027-09-11',135000.00,'VND',20,10,20,'https://res.cloudinary.com/tripfinity-img/image/upload/v1765869492/assets/59c352c8-b678-4c2e-861c-ad80c2965572.jpg','[]','[\"hot_deal\",\"recommended\"]','published','public_',1,2,'moderate','Trung tâm Châu Đốc','Bến xe Châu Đốc','vietnamese,english','[\"vietnamese\", \"english\"]','Tour 2 ngày khám phá núi rừng và sinh thái An Giang','[{\"day\": 1, \"title\": \"Châu Đốc – Núi Cấm\", \"activities\": [\"Miếu Bà Chúa Xứ\", \"Cáp treo Núi Cấm\"]}, {\"day\": 2, \"title\": \"Trà Sư\", \"activities\": [\"Xuồng rừng tràm\", \"Chụp ảnh thiên nhiên\"]}]','hotel,meals,transport,guide','flights,visa,personal_expenses','[\"hotel\", \"meals\", \"transport\", \"guide\"]','[\"flights\", \"visa\", \"personal_expenses\"]','Hủy trước 5 ngày','Giá bao gồm xe, ăn uống theo chương trình, vé tham quan. Không bao gồm chi phí cá nhân.','group','[\"culture\", \"nature\", \"mountain\"]','[\"pickup\", \"professional_guide\"]','tour-chau-doc-nui-cam-tra-su-2-ngay','Tour Châu Đốc Núi Cấm Trà Sư 2 Ngày','Khám phá An Giang 2 ngày với Núi Cấm và rừng tràm Trà Sư.','2025-12-16 05:09:51','2025-12-16 05:09:51','2025-12-16 14:26:43'),(3,2,1,'Tour Long Xuyên – Cù Lao Giêng – Làng Nghề 1 Ngà